namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public string ImageUrl { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0
        ? Math.Round(Ratings.Average(), 1)
        : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
                Ratings = [5, 4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEgg yolks\nPecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk egg yolks with grated Pecorino and pepper.\n4. Toss hot pasta with guanciale, then quickly stir in egg mixture.\n5. Serve immediately with extra cheese and pepper.",
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
                Steps = "1. Marinate chicken in yogurt and spices for at least 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pan.\n4. Add tomato sauce, garam masala, and cream.\n5. Simmer sauce, then add chicken pieces.\n6. Serve with basmati rice or naan.",
                Ratings = [5, 4, 4, 5]
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
                Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nEggs",
                Steps = "1. Soak rice noodles in warm water for 20 minutes.\n2. Mix tamarind paste, fish sauce, and sugar for the sauce.\n3. Stir-fry tofu until golden, set aside.\n4. Scramble eggs in the same pan.\n5. Add noodles and sauce, toss until coated.\n6. Add tofu, bean sprouts, and peanuts.\n7. Serve with lime wedges and green onions.",
                Ratings = [4, 4, 3, 5]
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nCumin\nChili powder\nGarlic powder\nOnion",
                Steps = "1. Brown ground beef with diced onion.\n2. Season with cumin, chili powder, and garlic powder.\n3. Warm taco shells in the oven.\n4. Fill shells with seasoned beef.\n5. Top with lettuce, tomato, cheese, and sour cream.",
                Ratings = [4, 5, 4]
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic",
                Steps = "1. Halve and pit avocados, scoop into a bowl.\n2. Mash with a fork to desired consistency.\n3. Stir in lime juice, diced onion, tomato, jalapeño, and cilantro.\n4. Season with salt and garlic.\n5. Serve immediately with tortilla chips.",
                Ratings = [5, 5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 7, Title = "Miso Soup", Category = "Japanese",
                Ingredients = "Dashi stock\nMiso paste\nTofu\nWakame seaweed\nGreen onions",
                Steps = "1. Bring dashi stock to a simmer.\n2. Add cubed tofu and rehydrated wakame.\n3. Remove from heat and dissolve miso paste into the broth.\n4. Garnish with sliced green onions.\n5. Serve immediately — do not boil after adding miso.",
                Ratings = [4, 4, 5]
            },
            new Recipe
            {
                Id = 8, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Ingredients = "Butter\nSugar\nBrown sugar\nEggs\nVanilla extract\nFlour\nBaking soda\nSalt\nChocolate chips",
                Steps = "1. Cream butter with sugars until fluffy.\n2. Beat in eggs and vanilla.\n3. Mix in flour, baking soda, and salt.\n4. Fold in chocolate chips.\n5. Drop spoonfuls onto baking sheet.\n6. Bake at 375°F (190°C) for 9-11 minutes.\n7. Cool on baking sheet for 5 minutes.",
                Ratings = [5, 5, 4, 5, 5]
            },
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public Recipe AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

@using RecipeShare.Services
@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= _selectedRating ? "★" : "☆")
        </span>
    }
    <span class="rating-info">
        @if (_justRated)
        {
            <span class="text-success">Thanks for rating!</span>
        }
        (@Recipe.Ratings.Count ratings, avg @Recipe.AverageRating)
    </span>
</div>

@code {
    [Parameter, EditorRequired]
    public Models.Recipe Recipe { get; set; } = default!;

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private bool _justRated;

    private void Rate(int stars)
    {
        _selectedRating = stars;
        RecipeService.AddRating(Recipe.Id, stars);
        _justRated = true;
    }
}

@page "/"
@using RecipeShare.Services

<PageTitle>RecipeShare — Home</PageTitle>

<h1>🍽️ RecipeShare</h1>
<p class="lead">Discover and share your favorite recipes from around the world.</p>

<h2>Browse by Category</h2>

<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mt-2">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3 class="card-title">
                        <span class="category-icon">@GetCategoryIcon(category)</span>
                        @category
                    </h3>
                    <p class="card-text text-muted">
                        @RecipeService.GetByCategory(category).Count recipe(s)
                    </p>
                    <a href="/recipes/@category" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="mt-5 text-center">
    <h4>Have a recipe to share?</h4>
    <a href="/submit" class="btn btn-success btn-lg">Submit a Recipe</a>
</div>

@code {
    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private static string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🥘",
        "Mexican" => "🌮",
        "Japanese" => "🍣",
        "Desserts" => "🍪",
        _ => "🍴"
    };
}

@page "/recipes/{Category}"
@using RecipeShare.Models
@using RecipeShare.Services

<PageTitle>@Category Recipes — RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@Category</li>
    </ol>
</nav>

<h1>@Category Recipes</h1>

@if (_recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 g-4 mt-2">
        @foreach (var recipe in _recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ★ @recipe.AverageRating (@recipe.Ratings.Count ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter]
    public string Category { get; set; } = string.Empty;

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<Recipe> _recipes = [];

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetByCategory(Category);
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services

<PageTitle>@(_recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        @if (_recipe is not null)
        {
            <li class="breadcrumb-item"><a href="/recipes/@_recipe.Category">@_recipe.Category</a></li>
            <li class="breadcrumb-item active">@_recipe.Title</li>
        }
    </ol>
</nav>

@if (_recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <h1>@_recipe.Title</h1>
    <span class="badge bg-secondary mb-3">@_recipe.Category</span>

    <StarRating Recipe="_recipe" />

    <div class="row mt-4">
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">🥄 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var item in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <li class="list-group-item">@item</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">📝 Steps</h5></div>
                <div class="card-body">
                    @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                    {
                        <p>@step</p>
                    }
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetById(Id);
    }
}

@page "/submit"
@using RecipeShare.Services
@rendermode InteractiveServer

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@_title</strong>" has been added.</p>
        <a href="/recipe/@_submittedId" class="btn btn-primary me-2">View Recipe</a>
        <button class="btn btn-outline-secondary" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">— Select a category —</option>
                @foreach (var cat in RecipeService.GetCategories())
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients"
                           placeholder="One ingredient per line" />
            <ValidationMessage For="() => _model.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="_model.Steps"
                           placeholder="Describe each step on a new line" />
            <ValidationMessage For="() => _model.Steps" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private RecipeFormModel _model = new();
    private bool _submitted;
    private string _title = string.Empty;
    private int _submittedId;

    private void HandleSubmit()
    {
        var recipe = RecipeService.AddRecipe(
            _model.Title, _model.Category, _model.Ingredients, _model.Steps);
        _title = recipe.Title;
        _submittedId = recipe.Id;
        _submitted = true;
    }

    private void Reset()
    {
        _model = new();
        _submitted = false;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        [System.ComponentModel.DataAnnotations.StringLength(100)]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = string.Empty;
    }
}

